-- Daily-sound schedule for @handstrudel's seed posts (21 days).
-- Generated by scripts/seed-official/schedule-sql.mjs from posts.json. Needs PR #112's migration.
-- Change the start day (a UTC date) on the next line if needed, then run the whole statement.
with settings as (select date '2026-12-01' as start_day),
plan(day_offset, caption, title, note) as (
  values
    (0, 'Four chords, one slow melody. Grand Piano in C major, played with two hands in the air.',
     'Dreamy Piano', 'The classic four chords on Grand Piano. Hold a chord with your left hand and sing a melody with your right.'),
    (1, 'Lo-fi Rhodes in A minor for your study playlist. Play this sound and loop your own.',
     'Lo-fi Rhodes', 'Warm Rhodes in A minor at 74 BPM. Keep it slow and leave space between notes.'),
    (2, 'Campfire nylon guitar in D major. Simple enough to learn tonight.',
     'Campfire Nylon', 'Nylon guitar in D major. Try strumming the chords and answering with short melody runs.'),
    (3, 'Strings Ensemble in D minor. Every movie trailer starts somewhere.',
     'Cinematic Strings', 'Big strings in D minor. Long notes, slow hands, then go up an octave for the ending.'),
    (4, 'Sunday morning in G major. Coffee, sunlight, Grand Piano.',
     'Sunday Piano', 'A bright G major piano tune. Take it at your own tempo.'),
    (5, 'D Dorian on Rhodes. That raised sixth is where the soul lives.',
     'Neo-Soul Rhodes', 'Rhodes in D Dorian, rocking between the one and four chords. Lean on the 7th.'),
    (6, 'Front porch fiddle in D major. Hands up, feet tapping.',
     'Front Porch Fiddle', 'A quick violin tune in D major at 120 BPM. Eighth notes, big smile.'),
    (7, 'A whole choir in your pocket. C minor, Choir Aahs, no singers needed.',
     'Pocket Choir', 'Choir Aahs in C minor. Hold each note and let the chords breathe.'),
    (8, 'A little bossa nova on nylon guitar, A minor at 108.',
     'Bossa Nylon', 'Nylon guitar in A minor with a bossa lilt. Play the melody a little ahead of the beat.'),
    (9, 'Rain on the window, E minor on the piano.',
     'Rainy Window Piano', 'Grand Piano in E minor at 72 BPM. Quiet, slow, a little sad.'),
    (10, 'Indie clean guitar in E minor. Same four chords as half your playlist.',
     'Indie Clean Guitar', 'Clean electric guitar in E minor. Arpeggiate up the wheel, then hold the high note.'),
    (11, 'Walking upright bass in F. One note per beat, never stops moving.',
     'Walking Upright Bass', 'Upright Bass in F major. One note per beat, stepping toward the next chord.'),
    (12, 'The world’s smallest violin, now in B minor.',
     'Sad Violin', 'Solo violin in B minor. Slide slowly between the notes for the full effect.'),
    (13, 'Golden hour Rhodes in F major. Starts on the four chord so it never quite lands.',
     'Golden Hour Rhodes', 'Rhodes in F major starting on IV. A warm, unresolved loop.'),
    (14, 'Anthem strings in B-flat. Big notes, bigger feelings.',
     'Anthem Strings', 'Strings Ensemble in B-flat major. Hold every note for two beats and go high at the end.'),
    (15, 'A Dorian on clean guitar, the classic one-to-four groove.',
     'Dorian Guitar', 'Clean guitar in A Dorian, moving between the one and four chords. Bluesy but bright.'),
    (16, 'Cathedral choir in F major. Long notes and a lot of echo.',
     'Cathedral Choir', 'Choir Aahs in F major. Two beats per note, no rush.'),
    (17, 'Upright bass groove in G Dorian. Bass players, this one is yours.',
     'Upright Dorian Groove', 'Upright Bass in G Dorian. A funky one-to-four riff with ghosted repeats.'),
    (18, 'Midnight Rhodes in C minor. Lights low, volume lower.',
     'Midnight Rhodes', 'Rhodes in C minor at 70 BPM. Let the minor 7th ring.'),
    (19, 'Violin sunrise in A major. Slow start, big finish.',
     'Violin Sunrise', 'Solo violin in A major. Build from low and slow to the high C-sharp.'),
    (20, 'Haunted choir in D minor. Play it with the lights off.',
     'Haunted Choir', 'Choir Aahs in D minor at 60 BPM. Slow, dark, and just a bit spooky.')
),
targets as (
  select s.start_day + plan.day_offset as day, v.id as video_id, plan.title, plan.note
  from plan cross join settings s
  join public.profiles p on p.username = 'handstrudel'
  join public.videos v on v.user_id = p.id and v.caption = plan.caption and not v.hidden
  where s.start_day + plan.day_offset >= (now() at time zone 'utc')::date
    and not exists (select 1 from public.daily_sounds d where d.day = s.start_day + plan.day_offset and d.source = 'scheduled')
)
select t.day, t.title, (public.schedule_daily_sound(t.day, t.video_id, t.title, t.note)).video_id as scheduled_video
from targets t
order by t.day;
